// Unit tests of OAuthTokenProvider. The service account tests use a throwaway RSA key that is generated by the test
// with the `openssl` command line tool (nothing is committed, nothing real is read); they are skipped without it.

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:firebase_app_dart/firebase_app_dart.dart';
import 'package:firebase_auth_providers_dart/firebase_auth_providers_dart.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:test/test.dart';

import 'fakes.dart';

void main() {
  String? skip;
  try {
    if (Process.runSync('openssl', <String>['version']).exitCode != 0) {
      skip =
          '`openssl version` failed: the test needs openssl to make a throwaway key';
    }
  } on ProcessException {
    skip =
        'openssl is not installed: the test needs it to make a throwaway key';
  }

  group('OAuthTokenProvider', () {
    late FakeClock clock;
    late int fetches;
    late OAuthTokenProvider provider;
    Future<OAuthAccessToken> Function()? fetchOverride;

    setUp(() {
      clock = FakeClock();
      fetches = 0;
      fetchOverride = null;
      provider = OAuthTokenProvider(() async {
        fetches++;
        if (fetchOverride != null) {
          return fetchOverride!();
        }
        return OAuthAccessToken(
          'token-$fetches',
          clock.now.add(const Duration(hours: 1)),
        );
      }, clock: clock.call);
    });

    test('there is no user and no token change event', () async {
      expect(provider.uid, isNull);
      expect(await provider.onTokenChanged.isEmpty, isTrue);
    });

    test(
      'a token is fetched once and reused until five minutes before expiry',
      () async {
        expect(
          fetches,
          0,
          reason: 'nothing is fetched before a token is needed',
        );
        expect(
          (await provider.getAccessToken(forceRefresh: false)).token,
          'token-1',
        );
        clock.advance(const Duration(minutes: 54, seconds: 59));
        expect(
          (await provider.getAccessToken(forceRefresh: false)).token,
          'token-1',
        );
        expect(fetches, 1);

        clock.advance(const Duration(seconds: 2));
        expect(
          (await provider.getAccessToken(forceRefresh: false)).token,
          'token-2',
        );
        expect(fetches, 2);
      },
    );

    test('forceRefresh fetches a new token', () async {
      await provider.getAccessToken(forceRefresh: false);
      expect(
        (await provider.getAccessToken(forceRefresh: true)).token,
        'token-2',
      );
    });

    test('concurrent requests share one fetch', () async {
      final Completer<OAuthAccessToken> pending = Completer<OAuthAccessToken>();
      fetchOverride = () => pending.future;
      final Future<List<GetTokenResult>> results =
          Future.wait(<Future<GetTokenResult>>[
            provider.getAccessToken(forceRefresh: false),
            provider.getAccessToken(forceRefresh: true),
          ]);
      await pump();
      pending.complete(
        OAuthAccessToken('shared', clock.now.add(const Duration(hours: 1))),
      );
      expect((await results).map((GetTokenResult r) => r.token), <String>[
        'shared',
        'shared',
      ]);
      expect(fetches, 1);
    });

    test(
      'a failed fetch is reported and the next request tries again',
      () async {
        fetchOverride = () async => throw StateError('no credentials');
        await expectLater(
          provider.getAccessToken(forceRefresh: false),
          throwsStateError,
        );
        fetchOverride = null;
        expect(
          (await provider.getAccessToken(forceRefresh: false)).token,
          'token-2',
        );
      },
    );

    test('the string form of a token hides it', () {
      expect(
        '${OAuthAccessToken('secret-token', DateTime.utc(2026))}',
        isNot(contains('secret-token')),
      );
    });
  });

  group('service account', () {
    late Directory temp;
    late Map<String, Object?> keyFile;
    late FakeClock clock;
    late List<http.Request> requests;
    late Future<http.Response> Function(http.Request request) handler;

    setUp(() {
      temp = Directory.systemTemp.createTempSync('auth_providers_key_');
      // A throwaway key pair: PKCS#8 private key (as in a key file of Google Cloud) and its public key.
      ProcessResult result = Process.runSync('openssl', <String>[
        'genpkey',
        '-algorithm',
        'RSA',
        '-pkeyopt',
        'rsa_keygen_bits:2048',
        '-out',
        '${temp.path}/key.pem',
      ]);
      expect(result.exitCode, 0, reason: '${result.stderr}');
      result = Process.runSync('openssl', <String>[
        'pkey',
        '-in',
        '${temp.path}/key.pem',
        '-pubout',
        '-out',
        '${temp.path}/public.pem',
      ]);
      expect(result.exitCode, 0, reason: '${result.stderr}');
      keyFile = <String, Object?>{
        'type': 'service_account',
        'project_id': 'demo-test',
        'private_key_id': 'throwaway',
        'private_key': File('${temp.path}/key.pem').readAsStringSync(),
        'client_email': 'kit@demo-test.iam.gserviceaccount.com',
        'client_id': '1234567890',
      };
      clock = FakeClock();
      requests = <http.Request>[];
      int issued = 0;
      handler = (http.Request request) async => http.Response(
        jsonEncode(<String, Object?>{
          'access_token': 'ya29.token-${++issued}',
          'expires_in': 3599,
          'token_type': 'Bearer',
        }),
        200,
      );
    });

    tearDown(() => temp.deleteSync(recursive: true));

    OAuthTokenProvider create({Object? json, List<String>? scopes}) =>
        OAuthTokenProvider.serviceAccount(
          json ?? keyFile,
          scopes: scopes ?? OAuthTokenProvider.datastoreScopes,
          httpClient: MockClient((http.Request request) {
            requests.add(request);
            return handler(request);
          }),
          clock: clock.call,
        );

    Map<String, Object?> decode(String part) =>
        jsonDecode(utf8.decode(base64Url.decode(base64Url.normalize(part))))
            as Map<String, Object?>;

    test('exchanges a signed assertion for an access token', () async {
      final OAuthTokenProvider provider = create();
      expect(requests, isEmpty);
      final GetTokenResult token = await provider.getAccessToken(
        forceRefresh: false,
      );
      expect(token.token, 'ya29.token-1');
      expect(token.claims, isEmpty, reason: 'an access token is not a JWT');

      final http.Request request = requests.single;
      expect(request.method, 'POST');
      expect(request.url.toString(), 'https://oauth2.googleapis.com/token');
      expect(
        request.bodyFields['grant_type'],
        'urn:ietf:params:oauth:grant-type:jwt-bearer',
      );
      final List<String> parts = request.bodyFields['assertion']!.split('.');
      expect(parts, hasLength(3));
      expect(decode(parts[0]), <String, Object?>{'alg': 'RS256', 'typ': 'JWT'});
      final int now = clock.now.millisecondsSinceEpoch ~/ 1000;
      expect(decode(parts[1]), <String, Object?>{
        'iss': 'kit@demo-test.iam.gserviceaccount.com',
        'scope': 'https://www.googleapis.com/auth/datastore',
        'aud': 'https://oauth2.googleapis.com/token',
        'iat': now - 20,
        'exp': now - 20 + 3600,
      });

      // The signature is the RS256 signature of the first two parts, by the key of the key file.
      File(
        '${temp.path}/signed.txt',
      ).writeAsStringSync('${parts[0]}.${parts[1]}');
      File(
        '${temp.path}/signature.bin',
      ).writeAsBytesSync(base64Url.decode(base64Url.normalize(parts[2])));
      final ProcessResult verify = Process.runSync('openssl', <String>[
        'dgst',
        '-sha256',
        '-verify',
        '${temp.path}/public.pem',
        '-signature',
        '${temp.path}/signature.bin',
        '${temp.path}/signed.txt',
      ]);
      expect(verify.exitCode, 0, reason: '${verify.stdout}${verify.stderr}');
      expect('${verify.stdout}', contains('Verified OK'));
    });

    test(
      'accepts the content of the key file as a string, and other scopes',
      () async {
        final OAuthTokenProvider provider = create(
          json: jsonEncode(keyFile),
          scopes: <String>['scope-a', 'scope-b'],
        );
        await provider.getAccessToken(forceRefresh: false);
        expect(
          decode(
            requests.single.bodyFields['assertion']!.split('.')[1],
          )['scope'],
          'scope-a scope-b',
        );
      },
    );

    test('the token is refreshed five minutes before it expires', () async {
      final OAuthTokenProvider provider = create();
      await provider.getAccessToken(forceRefresh: false);
      // expires_in was 3599 s.
      clock.advance(const Duration(seconds: 3599 - 301));
      expect(
        (await provider.getAccessToken(forceRefresh: false)).token,
        'ya29.token-1',
      );
      expect(requests, hasLength(1));
      clock.advance(const Duration(seconds: 2));
      expect(
        (await provider.getAccessToken(forceRefresh: false)).token,
        'ya29.token-2',
      );
      expect(requests, hasLength(2));
      // The new assertion is issued at the new time.
      expect(
        decode(requests.last.bodyFields['assertion']!.split('.')[1])['iat'],
        clock.now.millisecondsSinceEpoch ~/ 1000 - 20,
      );
    });

    test('errors of the token endpoint are mapped', () async {
      handler = (http.Request request) async => http.Response(
        jsonEncode(<String, Object?>{
          'error': 'invalid_grant',
          'error_description': 'Invalid JWT Signature.',
        }),
        400,
      );
      final OAuthTokenProvider provider = create();
      await expectLater(
        provider.getAccessToken(forceRefresh: false),
        throwsA(
          isA<FirebaseAuthProviderException>()
              .having(
                (FirebaseAuthProviderException e) => e.code,
                'code',
                'invalid-credential',
              )
              .having(
                (FirebaseAuthProviderException e) => e.message,
                'message',
                contains('Invalid JWT Signature'),
              )
              .having(
                (FirebaseAuthProviderException e) => e.httpStatus,
                'status',
                400,
              ),
        ),
      );

      handler = (http.Request request) =>
          throw http.ClientException('offline', request.url);
      await expectLater(
        provider.getAccessToken(forceRefresh: false),
        throwsA(
          isA<FirebaseAuthProviderException>().having(
            (FirebaseAuthProviderException e) => e.code,
            'code',
            'network-request-failed',
          ),
        ),
      );
    });

    test('something that is not a key file is rejected without quoting it', () {
      for (final Object bad in <Object>[
        <String, Object?>{},
        <String, Object?>{...keyFile, 'type': 'authorized_user'},
        <String, Object?>{...keyFile}..remove('client_email'),
        'not json',
      ]) {
        expect(
          () => OAuthTokenProvider.serviceAccount(bad),
          throwsA(
            isA<ArgumentError>().having(
              (ArgumentError e) => '$e',
              'text',
              isNot(contains('PRIVATE KEY')),
            ),
          ),
        );
      }
    });
  }, skip: skip);
}
